use crate::connection_geometry::{ConnectionRegion,WorldConnectionPoint};
use crate::resources::{BaseResource,ConnectionPoint,ConnectionSites};
use crate::structural_material::StructuralMaterial;
use serde::{Deserialize,Serialize};
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub struct Placement{pub x:f64,pub y:f64,pub rotation_radians:f64}
#[derive(Serialize,Clone,Debug,PartialEq)]pub struct StructuralUnit{pub material:StructuralMaterial,pub placement:Placement}
impl StructuralUnit{pub fn new(resource_name:impl Into<String>,placement:Placement)->Self{Self{material:StructuralMaterial::single(resource_name),placement}}pub fn from_material(material:crate::resources::Material,placement:Placement)->Option<Self>{Some(Self{material:StructuralMaterial::from_material(material)?,placement})}pub fn resource_name(&self)->Option<&str>{let[c]=self.material.composition()else{return None};if !self.material.is_structured()&&(c.amount-1.0).abs()<=1e-12{Some(c.resource.as_str())}else{None}}pub fn properties(&self,catalog:&[BaseResource])->Option<crate::resources::ResourceProperties>{if !self.material.is_valid()||!self.material.resolves_in_catalog(catalog){return None}Some(self.material.weighted_properties(catalog))}pub fn connection_sites(&self,catalog:&[BaseResource])->Option<ConnectionSites>{self.material.connection_sites(catalog)}pub fn shape<'a>(&self,catalog:&'a[BaseResource])->Option<&'a crate::resources::Shape>{self.material.shape(catalog)}}
impl<'de>Deserialize<'de>for StructuralUnit{fn deserialize<D>(deserializer:D)->Result<Self,D::Error>where D:serde::Deserializer<'de>{#[derive(Deserialize)]struct Stored{material:Option<StructuralMaterial>,resource_name:Option<String>,placement:Placement}let s=Stored::deserialize(deserializer)?;let m=match s.material{Some(m)=>m,None=>StructuralMaterial::single(s.resource_name.ok_or_else(||serde::de::Error::custom("structural unit has no material"))?)};if !m.is_valid(){return Err(serde::de::Error::custom("invalid structural material"))}Ok(Self{material:m,placement:s.placement})}}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq,Eq,Hash)]pub struct ConnectionSiteRef{pub unit_index:usize,pub point_index:usize}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub enum ConnectionEndpoint{Corner{point_index:usize},Boundary{angle_radians:f64},Fluid{x:f64,y:f64}}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub struct BondEndpoint{pub unit_index:usize,pub location:ConnectionEndpoint}
impl ConnectionEndpoint{pub fn region(self,unit:&StructuralUnit,catalog:&[BaseResource])->Option<ConnectionRegion>{match self{Self::Corner{point_index}=>match unit.connection_sites(catalog)?{ConnectionSites::Corners(points)=>points.get(point_index).copied().map(|p|ConnectionRegion::Corner(crate::connection_geometry::transform_connection_point(p,unit.placement.x,unit.placement.y,unit.placement.rotation_radians))),_=>None},Self::Boundary{..}=>match unit.connection_sites(catalog)?{ConnectionSites::Circumference{radius}=>Some(ConnectionRegion::Boundary{center_x:unit.placement.x,center_y:unit.placement.y,radius}),_=>None},Self::Fluid{..}=>match unit.connection_sites(catalog)?{ConnectionSites::Undetermined=>{let radius=unit.shape(catalog)?.form.fluid_contact_radius()?;Some(ConnectionRegion::Fluid{center_x:unit.placement.x,center_y:unit.placement.y,effective_radius:radius})},_=>None}}}pub fn world_point(self,unit:&StructuralUnit,catalog:&[BaseResource])->Option<WorldConnectionPoint>{let(local_x,local_y,nx,ny)=match self{Self::Corner{point_index}=>{let ConnectionSites::Corners(points)=unit.connection_sites(catalog)?else{return None};let p=*points.get(point_index)?;(p.x,p.y,p.direction_radians.cos(),p.direction_radians.sin())},Self::Boundary{angle_radians}=>{if !angle_radians.is_finite(){return None}let ConnectionSites::Circumference{radius}=unit.connection_sites(catalog)?else{return None};let(nx,ny)=(angle_radians.cos(),angle_radians.sin());(radius*nx,radius*ny,nx,ny)},Self::Fluid{x,y}=>{if !x.is_finite()||!y.is_finite(){return None}let ConnectionSites::Undetermined=unit.connection_sites(catalog)?else{return None};let radius=unit.shape(catalog)?.form.fluid_contact_radius()?;if !radius.is_finite()||radius<0.0||x.hypot(y)>radius+1e-12{return None}(x,y,0.0,0.0)}};if !unit.placement.x.is_finite()||!unit.placement.y.is_finite()||!unit.placement.rotation_radians.is_finite(){return None}let(s,c)=unit.placement.rotation_radians.sin_cos();Some(WorldConnectionPoint{x:unit.placement.x+local_x*c-local_y*s,y:unit.placement.y+local_x*s+local_y*c,normal_x:nx*c-ny*s,normal_y:nx*s+ny*c})}pub fn same_location(self,o:Self)->bool{match(self,o){(Self::Corner{point_index:a},Self::Corner{point_index:b})=>a==b,(Self::Boundary{angle_radians:a},Self::Boundary{angle_radians:b})=>(a-b).abs()<=1e-12,(Self::Fluid{x:ax,y:ay},Self::Fluid{x:bx,y:by})=>(ax-bx).hypot(ay-by)<=1e-12,_=>false}}}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq)]pub struct Bond{pub endpoint_a:BondEndpoint,pub endpoint_b:BondEndpoint,pub strength:f64,#[serde(default)]pub bond_energy:f64}
impl Bond{pub fn touches(&self,u:usize,l:ConnectionEndpoint)->bool{(self.endpoint_a.unit_index==u&&self.endpoint_a.location.same_location(l))||(self.endpoint_b.unit_index==u&&self.endpoint_b.location.same_location(l))}pub fn has_same_identity(&self,o:&Bond)->bool{(self.endpoint_a.unit_index==o.endpoint_a.unit_index&&self.endpoint_a.location.same_location(o.endpoint_a.location)&&self.endpoint_b.unit_index==o.endpoint_b.unit_index&&self.endpoint_b.location.same_location(o.endpoint_b.location))||(self.endpoint_a.unit_index==o.endpoint_b.unit_index&&self.endpoint_a.location.same_location(o.endpoint_b.location)&&self.endpoint_b.unit_index==o.endpoint_a.unit_index&&self.endpoint_b.location.same_location(o.endpoint_a.location))}pub fn is_valid(&self,n:usize,f:impl Fn(BondEndpoint)->bool)->bool{self.endpoint_a.unit_index<n&&self.endpoint_b.unit_index<n&&self.endpoint_a.unit_index!=self.endpoint_b.unit_index&&self.bond_energy.is_finite()&&self.bond_energy>=0.0&&f(self.endpoint_a)&&f(self.endpoint_b)}}
fn units_strictly_overlap(a:&StructuralUnit,b:&StructuralUnit,c:&[BaseResource])->bool{let(Some(fa),Some(fb))=(a.shape(c),b.shape(c))else{return false};let pa=crate::material_geometry::PlacedMaterialPart{part_index:0,form:fa.form.clone(),placement:a.placement};let pb=crate::material_geometry::PlacedMaterialPart{part_index:1,form:fb.form.clone(),placement:b.placement};if !crate::material_geometry::placed_forms_overlap(&pa,&pb,0.0){return false}let dx=b.placement.x-a.placement.x;let dy=b.placement.y-a.placement.y;let d=dx.hypot(dy);let(sx,sy)=if d>1e-12{(dx/d,dy/d)}else{(1.0,0.0)};let scale=pa.form.rigid_bounding_radius().unwrap_or(1.0).max(pb.form.rigid_bounding_radius().unwrap_or(1.0)).max(1.0);let e=1e-8*scale;let shifted=crate::material_geometry::PlacedMaterialPart{part_index:0,form:pa.form.clone(),placement:Placement{x:a.placement.x-sx*e,y:a.placement.y-sy*e,rotation_radians:a.placement.rotation_radians}};crate::material_geometry::placed_forms_overlap(&shifted,&pb,0.0)}
#[derive(Serialize,Deserialize,Clone,Debug,Default)]pub struct OrganismStructure{pub units:Vec<StructuralUnit>,pub bonds:Vec<Bond>}
impl OrganismStructure{pub fn new()->Self{Self::default()}pub(crate)fn push_bond_unchecked(&mut self,b:Bond)->usize{self.bonds.push(b);self.bonds.len()-1}pub fn add_unit(&mut self,u:StructuralUnit)->usize{self.units.push(u);self.units.len()-1}pub fn is_valid_bond(&self,b:&Bond,c:&[BaseResource])->bool{if !b.is_valid(self.units.len(),|e|self.endpoint_is_valid(e,c)){return false}if units_strictly_overlap(&self.units[b.endpoint_a.unit_index],&self.units[b.endpoint_b.unit_index],c){return false}if !crate::contact::bond_geometry_is_valid(self,b,c){return false}let(Some(a),Some(d))=(self.units[b.endpoint_a.unit_index].properties(c),self.units[b.endpoint_b.unit_index].properties(c))else{return false};let strength=crate::combine::bond_strength(a,d);strength.is_finite()&&(0.0..=1.0).contains(&strength)}fn endpoint_is_valid(&self,e:BondEndpoint,c:&[BaseResource])->bool{self.units.get(e.unit_index).and_then(|u|e.location.world_point(u,c)).is_some()}pub fn connection_site(&self,s:ConnectionSiteRef,c:&[BaseResource])->Option<ConnectionPoint>{match self.units.get(s.unit_index)?.connection_sites(c)?{ConnectionSites::Corners(p)=>p.get(s.point_index).copied(),_=>None}}pub fn available_connection_sites(&self,c:&[BaseResource])->Vec<ConnectionSiteRef>{let mut out=Vec::new();for i in 0..self.units.len(){let Some(ConnectionSites::Corners(p))=self.units[i].connection_sites(c)else{continue};for j in 0..p.len(){out.push(ConnectionSiteRef{unit_index:i,point_index:j})}}out}pub fn connected_components(&self)->Vec<Vec<usize>>{let mut a=vec![Vec::new();self.units.len()];for b in &self.bonds{let(x,y)=(b.endpoint_a.unit_index,b.endpoint_b.unit_index);if x<self.units.len()&&y<self.units.len(){a[x].push(y);a[y].push(x)}}let mut v=vec![false;self.units.len()];let mut out=Vec::new();for start in 0..self.units.len(){if v[start]{continue}let mut stack=vec![start];v[start]=true;let mut comp=Vec::new();while let Some(u)=stack.pop(){comp.push(u);for &n in &a[u]{if !v[n]{v[n]=true;stack.push(n)}}}comp.sort_unstable();out.push(comp)}out}pub fn component_connection_sites(&self,component:&[usize],c:&[BaseResource])->Vec<ConnectionSiteRef>{let set:std::collections::HashSet<usize>=component.iter().copied().collect();self.available_connection_sites(c).into_iter().filter(|s|set.contains(&s.unit_index)).collect()}pub fn connection_load(&self,u:usize,l:ConnectionEndpoint,_c:&[BaseResource])->f64{self.bonds.iter().filter(|b|b.touches(u,l)).map(|b|crate::combine::experimental_bond_strength(b.bond_energy)).sum()}pub fn connection_count(&self,u:usize,l:ConnectionEndpoint)->usize{self.bonds.iter().filter(|b|b.touches(u,l)).count()}pub fn break_bond(&mut self,i:usize)->Option<Bond>{(i<self.bonds.len()).then(||self.bonds.remove(i))}pub fn break_matching_bond(&mut self,t:Bond)->Option<Bond>{let i=self.bonds.iter().position(|b|b.has_same_identity(t))?;self.break_bond(i)}pub fn disconnect_point(&mut self,u:usize,l:ConnectionEndpoint)->Vec<Bond>{let mut out=Vec::new();let mut i=0;while i<self.bonds.len(){if self.bonds[i].touches(u,l){out.push(self.bonds.remove(i))}else{i+=1}}out}pub fn loaded_points(&self)->Vec<(usize,ConnectionEndpoint)>{let mut out=Vec::new();for b in &self.bonds{for e in[b.endpoint_a,b.endpoint_b]{if !out.iter().any(|(u,p)|*u==e.unit_index&&p.same_location(e.location)){out.push((e.unit_index,e.location))}}}out}}
pub fn formation_threshold(a:f64,b:f64,la:f64,lb:f64)->f64{let la=la.max(0.0);let lb=lb.max(0.0);((a+b)/2.0)*(1.0+la.sqrt()+lb.sqrt())}
